CREATE TABLE public.companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,cnpj text,address text NOT NULL DEFAULT '',demo boolean NOT NULL DEFAULT false);
GRANT SELECT,UPDATE ON public.companies TO authenticated; GRANT ALL ON public.companies TO service_role; ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,company_id uuid NOT NULL REFERENCES public.companies(id),role text NOT NULL CHECK(role IN ('Administrador','Gerente','Financeiro','Comprador','Estoquista','Produção','Vendedor','RH')),UNIQUE(user_id,company_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.current_company() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT company_id FROM public.user_roles WHERE user_id=auth.uid() ORDER BY id LIMIT 1 $$;
CREATE FUNCTION public.erp_allowed(module text,operation text DEFAULT 'read',tenant uuid DEFAULT public.current_company()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND company_id=tenant AND (role='Administrador' OR role='Gerente' AND operation<>'delete' OR operation='read' AND module='dashboard' OR role='Financeiro' AND module IN ('finance','reports') AND operation<>'delete' OR role='Comprador' AND module IN ('purchases','suppliers','inventory','products') AND operation IN ('read','create','update') OR role='Estoquista' AND module IN ('inventory','products','purchases') AND operation IN ('read','create','update') OR role='Produção' AND module IN ('production','inventory','products') AND operation IN ('read','create','update') OR role='Vendedor' AND module IN ('sales','customers','products','inventory') AND operation IN ('read','create','update') OR role='RH' AND module='hr' AND operation IN ('read','create','update'))) $$;
CREATE POLICY own_membership ON public.user_roles FOR SELECT TO authenticated USING(company_id=public.current_company());
CREATE POLICY own_company ON public.companies FOR SELECT TO authenticated USING(id=public.current_company()); CREATE POLICY edit_company ON public.companies FOR UPDATE TO authenticated USING(public.erp_allowed('settings','update',id)) WITH CHECK(id=public.current_company());
CREATE FUNCTION public.ensure_company(company_name text DEFAULT 'Minha padaria') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Conecte-se'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT public.current_company() INTO c; IF c IS NULL THEN INSERT INTO public.companies(name) VALUES(COALESCE(NULLIF(trim(company_name),''),'Minha padaria')) RETURNING id INTO c; INSERT INTO public.user_roles(user_id,company_id,role) VALUES(auth.uid(),c,'Administrador'); END IF; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.ensure_company(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ensure_company(text) TO authenticated;
CREATE FUNCTION public.assign_role(target_user uuid,target_role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.erp_allowed('settings','delete') THEN RAISE EXCEPTION 'Somente administrador'; END IF; IF target_user=auth.uid() THEN RAISE EXCEPTION 'Não altere seu próprio perfil'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target_user AND company_id<>public.current_company()) THEN RAISE EXCEPTION 'Usuário pertence a outra empresa'; END IF; INSERT INTO public.user_roles(user_id,company_id,role) VALUES(target_user,public.current_company(),target_role) ON CONFLICT(user_id,company_id) DO UPDATE SET role=excluded.role; END $$;
REVOKE ALL ON FUNCTION public.assign_role(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.assign_role(uuid,text) TO authenticated;
INSERT INTO public.companies(id,name,demo) VALUES('10000000-0000-4000-8000-000000000001','Padaria demonstração',true);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['products','suppliers','bom','demands','orders','movements','history'] LOOP EXECUTE format('ALTER TABLE public.%I ADD COLUMN company_id uuid DEFAULT public.current_company() REFERENCES public.companies(id)',t); EXECUTE format('UPDATE public.%I SET company_id=''10000000-0000-4000-8000-000000000001''',t); EXECUTE format('ALTER TABLE public.%I ALTER COLUMN company_id SET NOT NULL',t); END LOOP; END $$;
ALTER TABLE public.products ADD COLUMN sale_price numeric NOT NULL DEFAULT 0 CHECK(sale_price>=0),ADD COLUMN ncm text NOT NULL DEFAULT '',ADD COLUMN cfop text NOT NULL DEFAULT '',ADD COLUMN tax_code text NOT NULL DEFAULT '';
ALTER TABLE public.suppliers ADD COLUMN trade_name text NOT NULL DEFAULT '';
DROP INDEX public.product_name_unique; CREATE UNIQUE INDEX product_name_per_company ON public.products(company_id,lower(trim(name)));
CREATE OR REPLACE FUNCTION public.audit_erp() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.history(entity,record_id,action,before_data,after_data,user_id,company_id) VALUES(TG_TABLE_NAME,COALESCE(NEW.id,OLD.id),TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END,auth.uid(),COALESCE(NEW.company_id,OLD.company_id)); RETURN COALESCE(NEW,OLD); END $$;
DO $$ DECLARE t text; m text; p record; BEGIN FOR t,m IN SELECT * FROM (VALUES('products','products'),('suppliers','suppliers'),('bom','production'),('demands','production'),('orders','production'),('movements','inventory'),('history','reports')) x(t,m) LOOP FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,t); END LOOP; EXECUTE format('CREATE POLICY tenant_read ON public.%I FOR SELECT TO authenticated USING(company_id=public.current_company() AND public.erp_allowed(%L,''read''))',t,m); IF t NOT IN ('history','movements') THEN EXECUTE format('CREATE POLICY tenant_update ON public.%I FOR UPDATE TO authenticated USING(company_id=public.current_company() AND public.erp_allowed(%L,''update'')) WITH CHECK(company_id=public.current_company())',t,m); EXECUTE format('CREATE POLICY tenant_delete ON public.%I FOR DELETE TO authenticated USING(company_id=public.current_company() AND public.erp_allowed(%L,''delete''))',t,m); END IF; IF t<>'history' THEN EXECUTE format('CREATE POLICY tenant_insert ON public.%I FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company() AND public.erp_allowed(%L,''create''))',t,m); END IF; EXECUTE format('CREATE INDEX ON public.%I(company_id)',t); END LOOP; END $$;
DROP POLICY access ON public.categories; CREATE POLICY catalog_read ON public.categories FOR SELECT TO authenticated USING(true);
ALTER PUBLICATION supabase_realtime ADD TABLE public.products,public.orders;